head.script:
scwin.onpageload = function () {
    scwin.btn_search_onclick();
    // 팝업 레이어 초기화
    scwin.createPopupLayer();
};

// ============================================================================
// 팝업 관련 함수들
// ============================================================================

// 팝업 레이어 생성 함수
scwin.createPopupLayer = function() {
    var popupHtml = `
        <div id="customAlertPopup" style="
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.5);
            z-index: 9999;
            display: none;
        ">
            <div style="
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                backgroun,d: white;
                padding: 30px;
                border-radius: 8px;
                box-shadow: 0 4px 20px rgba(0,0,0,0.3);
                min-width: 350px;
                max-width: 500px;
                text-align: center;
            ">
                <div id="popupMessage" style="
                    margin-bottom: 25px; 
                    font-size: 15px; 
                    line-height: 1.5;
                    color: #333;
                    white-space: pre-wrap;
                "></div>
                <div>
                    <button id="popupConfirm" style="
                        background: #007bff;
                        color: white;
                        border: none;
                        padding: 10px 20px;
                        margin: 0 5px;
                        border-radius: 4px;
                        cursor: pointer;
                        font-size: 14px;
                        min-width: 60px;
                    ">확인</button>
                    <button id="popupCancel" style="
                        background: #6c757d;
                        color: white;
                        border: none;
                        padding: 10px 20px;
                        margin: 0 5px;
                        border-radius: 4px;
                        cursor: pointer;
                        font-size: 14px;
                        min-width: 60px;
                    ">취소</button>
                </div>
            </div>
        </div>
    `;

    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 팝업 표시 함수
scwin.showPopup = function(message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    messageEl.textContent = message;

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function() {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function() {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function() {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'block';
};

// ============================================================================
// 기본 CRUD 함수들 (팝업 적용)
// ============================================================================

scwin.btn_insert_onclick = function (e) {
    var _rowIdx = userList.insertRow();
    userList.setCellData(_rowIdx, "tenantId", "1");
};

scwin.btn_delete_onclick = function (e) {
    if (grd.getFocusedRowIndex() < 0) {
        scwin.showPopup("삭제할 행을 먼저 선택해주세요.");
        return;
    }
    userList.deleteRow(grd.getFocusedRowIndex());
};

scwin.btn_deleteRows_onclick = function (e) {
    var chkIdxArr = grd.getCheckedIndex("chk");
    if (chkIdxArr.length === 0) {
        scwin.showPopup("삭제할 행을 선택해주세요.");
        return;
    }
    userList.deleteRows(chkIdxArr);
};

scwin.btn_reset_onclick = function (e) {
    scwin.showPopup("모든 데이터를 초기화하시겠습니까?", true, function(result) {
        if (result) {
            userList.setData([]);
        }
    });
};

scwin.btn_search_onclick = function (e) {
    const tenantIdFromUrl = "1";

    var userDetailDataMap = $p.getComponentById("userDetail");
    if (userDetailDataMap) {
        userDetailDataMap.set("tenantId", tenantIdFromUrl);
    } else {
        scwin.showPopup("userDetail DataMap을 찾을 수 없습니다.");
        return;
    }

    console.log("사용자 목록 조회 실행");
    $p.executeSubmission("sbm_selectUserList");
};

// ============================================================================
// 다운로드 함수
// ============================================================================

scwin.btn_down_onclick = function (e) {
    var options = {
        fileName: "사용자관리.xlsx"
    };
    grd.advancedExcelDownload(options);
};

// ============================================================================
// 업로드 관련 함수들 (수정된 버전)
// ============================================================================

scwin.btn_upload_onclick = function (e) {
    console.log("Excel 업로드 시작");

    // 업로드 전 현재 데이터 개수 저장
    scwin.originalDataCount = userList.getTotalRow();
    console.log("업로드 전 데이터 개수:", scwin.originalDataCount);

    // 업로드 전 데이터 백업 (롤백용)
    scwin.originalDataBackup = userList.getAllJSON();
    console.log("업로드 전 데이터 백업 완료");

    try {
        var options = {
            headerExist: "1",
            type: "1",
            status: "C"
        };

        grd.advancedExcelUpload(options);
        console.log("업로드 함수 호출 완료");

    } catch (err) {
        console.error("업로드 함수 호출 중 에러 발생:", err);
        scwin.showPopup("업로드 실행 중 오류가 발생했습니다.");
    }
};

// Excel 업로드 완료 시 자동 호출되는 함수
scwin.grd_onexcelupload = function (e) {
    console.log("=== Excel 업로드 완료 ===");

    var allData = userList.getAllJSON();
    console.log("업로드 후 전체 데이터:", allData.length + "개");

    // 1. 역할 매핑부터 처리 (한글 → 코드)
    scwin.fixRoleMappingForAllData();

    // 2. tenantId 설정
    scwin.setTenantIdForAllData();

    // 3. 잠시 후 중복검사 실행 (DOM 업데이트 대기)
    setTimeout(function () {
        scwin.checkAllEmailDuplicates();
    }, 500);
};

// Excel 업로드 에러 시 호출되는 함수 (추가)
scwin.grd_onexceluploaderror = function(e) {
    console.error("Excel 업로드 에러:", e);
    scwin.showPopup("Excel 파일 업로드에 실패했습니다.\n\n해결방법:\n1. 새 Excel 파일에 데이터만 복사\n2. 하이퍼링크 제거\n3. .xlsx 형식으로 저장 후 재시도");

    // 원래 상태로 복원
    if (scwin.originalDataBackup) {
        userList.setJSON(scwin.originalDataBackup);
    }
};

// 모든 데이터의 역할 매핑 처리
scwin.fixRoleMappingForAllData = function () {
    console.log("=== 역할 매핑 처리 시작 ===");

    var roleMapping = {
        "관리자": "admin",
        "매니저": "manager", 
        "사용자": "user"
    };

    var totalRows = userList.getTotalRow();
    var mappedCount = 0;

    for (var i = 0; i < totalRows; i++) {
        var currentRole = userList.getCellData(i, "role");

        // 한글 역할명을 코드로 변환
        if (currentRole && roleMapping[currentRole]) {
            userList.setCellData(i, "role", roleMapping[currentRole]);
            mappedCount++;
            console.log(`행 ${i}: "${currentRole}" → "${roleMapping[currentRole]}"`);
        }

        // Excel 헤더 문제로 인한 컬럼명 매핑
        var rowData = userList.getRowJSON(i);
        if (rowData["성명_1"] && !userList.getCellData(i, "name")) {
            userList.setCellData(i, "name", rowData["성명_1"]);
        }
        if (rowData["이메일"] && !userList.getCellData(i, "email")) {
            userList.setCellData(i, "email", rowData["이메일"]);
        }
        if (rowData["비밀번호"] && !userList.getCellData(i, "password")) {
            userList.setCellData(i, "password", rowData["비밀번호"]);
        }
    }

    console.log(`역할 매핑 완료: ${mappedCount}개 행 처리`);
};

// 모든 데이터에 tenantId 설정
scwin.setTenantIdForAllData = function () {
    var totalRows = userList.getTotalRow();

    for (var i = 0; i < totalRows; i++) {
        if (!userList.getCellData(i, "tenantId")) {
            userList.setCellData(i, "tenantId", "1");
        }
    }

    console.log("tenantId 설정 완료");
};

// 전체 데이터에서 이메일 중복 검사 (팝업 적용)
scwin.checkAllEmailDuplicates = function () {
    console.log("=== 전체 이메일 중복 검사 시작 ===");

    var allData = userList.getAllJSON();
    var emailMap = {}; // 이메일별 행 인덱스들 저장
    var duplicateGroups = []; // 중복된 이메일 그룹들

    // 1. 이메일별로 행 인덱스들 수집
    for (var i = 0; i < allData.length; i++) {
        var email = userList.getCellData(i, "email");
        var name = userList.getCellData(i, "name");

        if (email && email.trim() !== "") {
            if (!emailMap[email]) {
                emailMap[email] = [];
            }
            emailMap[email].push({
                index: i,
                name: name || "이름없음",
                email: email
            });
        }
    }

    // 2. 중복된 이메일 찾기
    for (var email in emailMap) {
        if (emailMap[email].length > 1) {
            duplicateGroups.push({
                email: email,
                rows: emailMap[email]
            });
        }
    }

    console.log("중복된 이메일 그룹:", duplicateGroups);

    // 3. 중복이 있으면 사용자에게 선택지 제공
    if (duplicateGroups.length > 0) {
        scwin.showDuplicateEmailOptions(duplicateGroups);
    } else {
        scwin.showPopup("업로드 완료! 이메일 중복이 없습니다.\n총 " + allData.length + "개의 데이터가 있습니다.", true, function(result) {
            if (result) {
                scwin.btn_save_onclick();
            }
        });
    }
};

// 중복된 이메일에 대한 선택지 제공 함수 (팝업 적용)
scwin.showDuplicateEmailOptions = function (duplicateGroups) {
    console.log("중복 이메일 선택지 제공");

    var message = "업로드된 데이터에 중복된 이메일이 있습니다:\n\n";

    duplicateGroups.forEach(function (group, groupIndex) {
        message += `[ ${group.email} ]\n`;
        group.rows.forEach(function (row, rowIndex) {
            var isNew = row.index >= scwin.originalDataCount;
            var status = isNew ? "(새로 추가됨)" : "(기존 데이터)";
            message += `  ${rowIndex + 1}. ${row.name} ${status}\n`;
        });
        message += "\n";
    });

    message += "처리 방법을 선택하세요:\n";
    message += "확인: 새로 추가된 중복 데이터만 제거\n";
    message += "취소: 업로드 전체 취소";

    scwin.showPopup(message, true, function(result) {
        if (result) {
            // 새로 추가된 중복 데이터만 제거
            scwin.removeDuplicateNewData(duplicateGroups);
        } else {
            // 업로드 전체 취소
            scwin.rollbackUpload();
        }
    });
};

// 새로 추가된 중복 데이터 제거 함수 (팝업 적용)
scwin.removeDuplicateNewData = function (duplicateGroups) {
    var indicesToRemove = [];

    duplicateGroups.forEach(function (group) {
        group.rows.forEach(function (row) {
            // 새로 추가된 데이터만 제거 대상으로 추가
            if (row.index >= scwin.originalDataCount) {
                indicesToRemove.push(row.index);
            }
        });
    });

    // 중복 제거 및 역순 정렬 (높은 인덱스부터 제거)
    indicesToRemove = [...new Set(indicesToRemove)].sort(function (a, b) { return b - a; });

    console.log("제거할 인덱스들:", indicesToRemove);

    // 행 제거
    indicesToRemove.forEach(function (index) {
        userList.removeRow(index);
    });

    var remainingNewData = (userList.getTotalRow() - scwin.originalDataCount);
    var removedCount = indicesToRemove.length;

    if (remainingNewData > 0) {
        scwin.showPopup(`중복 제거 완료!\n제거된 데이터: ${removedCount}개\n추가된 데이터: ${remainingNewData}개`, true, function(result) {
            if (result) {
                scwin.btn_save_onclick();
            }
        });
    } else {
        scwin.showPopup("모든 새 데이터가 중복으로 인해 제거되었습니다.");
    }
};

scwin.rollbackUpload = function () {
    console.log("업로드 롤백");

    if (scwin.originalDataBackup) {
        userList.setJSON(scwin.originalDataBackup);
        scwin.showPopup("업로드가 취소되었습니다.");
    } else {
        scwin.showPopup("업로드가 취소되었습니다.", false, function() {
            scwin.btn_search_onclick();
        });
    }

    scwin.originalDataBackup = null;
};

// ============================================================================
// 저장 관련 함수들 (팝업 적용)
// ============================================================================

scwin.btn_save_onclick = function (e) {
    if (userList.getModifiedIndex().length === 0) {
        scwin.showPopup("저장할 변경사항이 없습니다.");
        return;
    }

    // --- [강화된 유효성 검사] ---
    for (var i = 0; i < userList.getTotalRow(); i++) {
        var status = userList.getRowStatus(i);

        if (status === "U" || status === "C") {
            var rowData = userList.getRowJSON(i);

            if (!rowData.name || rowData.name.trim() === "") {
                scwin.showPopup((i + 1) + "번째 행의 이름은 필수 입력 항목입니다.", false, function() {
                    grd.focusCell(i, "name");
                });
                return;
            }
            if (!rowData.email || rowData.email.trim() === "" || rowData.email === "******") {
                scwin.showPopup((i + 1) + "번째 행의 이메일은 필수 입력 항목입니다.", false, function() {
                    grd.focusCell(i, "email");
                });
                return;
            }
            // [추가] 역할(role) 필드 유효성 검사
            if (!rowData.role || rowData.role.trim() === "") {
                scwin.showPopup((i + 1) + "번째 행의 역할은 필수 선택 항목입니다.", false, function() {
                    grd.focusCell(i, "role");
                });
                return;
            }

            if (status === "C") {
                if (!rowData.password || rowData.password.trim() === "") {
                    scwin.showPopup((i + 1) + "번째 신규 행의 비밀번호는 필수 입력 항목입니다.", false, function() {
                        grd.focusCell(i, "password");
                    });
                    return;
                }
            }
        }
    }

    // --- 저장 전 비밀번호 값 처리 ---
    for (var i = 0; i < userList.getTotalRow(); i++) {
        var status = userList.getRowStatus(i);
        if (status === "U") {
            var password = userList.getCellData(i, "password");
            if (password === "******" || !password || password.trim() === "") {
                userList.setCellData(i, "password", "KEEP_EXISTING_PASSWORD");
            }
        }
    }

    scwin.showPopup("변경 내용을 저장하시겠습니까?", true, function(result) {
        if (result) {
            $p.executeSubmission("sbm_saveUserList");
        } else {
            scwin.btn_search_onclick();
        }
    });
};

// ============================================================================
// 서버 응답 처리 함수들 (팝업 적용)
// ============================================================================

scwin.sbm_selectUserList_submitdone = function (e) {
    var responseData = e.responseJSON;
    if (!responseData || !responseData.elData || !Array.isArray(responseData.elData.userVoList)) {
        userList.removeAll();
        console.error("서버로부터 유효한 사용자 목록을 받지 못했습니다.");
        return;
    }
    var userArray = responseData.elData.userVoList;
    userArray.forEach(function (user) {
        user.password = "******";
    });
    userList.setJSON(userArray);
};

scwin.sbm_saveUserList_submitdone = function (e) {
    scwin.showPopup("저장이 완료되었습니다.", false, function() {
        scwin.btn_search_onclick();
    });
};

// ============================================================================
// 이메일 중복 검사 (개별 입력 시) (팝업 적용)
// ============================================================================

scwin.grd_oncellindexchange = function (newRowIndex, newColIndex, oldRowIndex, oldColIndex) {
    const grid = $p.getComponentById("grd");
    const oldColId = grid.getColumnID(oldColIndex);

    if (oldColId === "email") {
        const emailValue = userList.getCellData(oldRowIndex, "email");

        if (!emailValue || emailValue.trim() === "") {
            return;
        }

        // 이메일 형식 검증
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(emailValue)) {
            scwin.showPopup("올바른 이메일 형식이 아닙니다.", false, function() {
                setTimeout(function () {
                    grid.focusCell(oldRowIndex, oldColIndex);
                }, 100);
            });
            return;
        }

        // 기존 데이터와 중복 검사
        scwin.checkEmailDuplicate(emailValue, oldRowIndex);
    }
};

scwin.checkEmailDuplicate = function (email, rowIndex) {
    console.log("이메일 중복검사:", email);

    $.ajax({
        url: '/InsWebApp/checkEmailByTenant.pwkjson',
        type: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({
            vo: {
                email: email,
                tenantId: "1"
            }
        }),
        success: function (response) {
            let emailCheckResult = response.emailCheckResult || response.elData?.emailCheckResult;

            if (emailCheckResult === "unavailable") {
                scwin.showPopup("'" + email + "'은(는) 이미 사용 중인 이메일입니다.\n다른 이메일을 입력해주세요.", false, function() {
                    const grid = $p.getComponentById("grd");
                    if (grid && userList.getRowStatus(rowIndex) === "C") {
                        userList.setCellData(rowIndex, "email", "");
                        setTimeout(function () {
                            grid.focusCell(rowIndex, grid.getColumnIndex("email"));
                        }, 100);
                    }
                });
            }
        },
        error: function (xhr, status, error) {
            scwin.showPopup("이메일 중복검사 중 오류가 발생했습니다.");
        }
    });
};

scwin.grd_oncellclick = function (row, col) {
    var grid = $p.getComponentById("grd");
    var colId = grid.getColumnID(col);

    // 클릭한 컬럼이 'password' 컬럼일 때만 동작
    if (colId === "password") {
        console.log("비밀번호 셀 클릭! row:", row, "colId:", colId);

        var currentValue = userList.getCellData(row, "password");

        if (currentValue === "******") {
            // 셀의 값을 비워주어 사용자가 새 비밀번호를 입력할 수 있게 함
            userList.setCellData(row, "password", "");
        }
    }
};
